package main
import("fmt";"go/ast";"go/parser";"go/token";"os";"path/filepath";"strings")
func main(){ targets:=map[string]bool{"NewEngine":true,"CompileToStatement":true,"GenUUID":true}; callers:=map[string]map[string]bool{}; fs:=token.NewFileSet(); filepath.Walk(".",func(path string, info os.FileInfo, err error)error{if err!=nil||info.IsDir()||!strings.HasSuffix(path,".go"){return nil}; f,e:=parser.ParseFile(fs,path,nil,0);if e!=nil{return nil}; var stack []string; ast.Inspect(f,func(n ast.Node)bool{switch x:=n.(type){case *ast.FuncDecl: stack=append(stack,x.Name.Name); if x.Body==nil{return false}; case *ast.CallExpr: var name string; switch fun:=x.Fun.(type){case *ast.Ident:name=fun.Name;case *ast.SelectorExpr:name=fun.Sel.Name}; if targets[name]&&len(stack)>0 {callers[name][strings.Join(stack,"/")]=true}}; return true}); return nil}); for n:=range targets{fmt.Println(n,len(callers[n]),callers[n])}}
